mapper.update:
update ${table}
set status = #{status}, last_sync_time = #{syncTime}
where corpid = #{corpid} and type = #{type}

mapper.select:
select wx_dept_id from ${table}
where corpid = #{corpid} and wx_dept_id = #{wxDeptId}
  and type = #{type} and status = #{status}

select wx_dept_id, dept_name, parent_id, status, no_bind
from ${table}
where corpid = #{corpid} and type = #{type} and status = #{status}
order by parent_id, dept_name, wx_dept_id

mapper.update:
update ${table}
set dept_name = #{e.deptName},
    parent_id = #{e.parentId},
    status = #{e.status},
    last_sync_time = #{e.lastSyncTime}
where corpid = #{e.corpid} and wx_dept_id = #{e.wxDeptId} and type = #{e.type}

update ${table}
set no_bind = #{noBind,jdbcType=INTEGER}
where corpid = #{corpid} and wx_dept_id = #{wxDeptId} and type = #{type}
